const r=require('./round-fixes.js');
const A=q=>r.verifiedRoundAnswer(r.normalizeQuestion(q),{});
const yes=[
 ['新任理事長什麼時候開始算','第一次理事會'],['新一屆理監事任期從哪一天開始算','第一次理事會'],['理事任期是從選舉那天起算嗎，什麼時候開始算','第一次理事會'],
 ['候選人要先登記嗎','參考名單'],['要參選理事需要先報名嗎','參考名單'],
 ['理事當選之後不想當怎麼辦','放棄當選'],['我被選上監事但是不想做了','放棄當選'],
 ['有人說選舉不公平可以怎樣','15日'],['改選過程有問題要向誰反映','15日'],
 ['改選結果要多久內報縣府','30日'],['選舉完幾天內要報主管機關','30日'],
 ['誰負責辦改選','理事會'],['改選由誰來辦','理事會'],
 ['改選一定要開大會嗎','通訊選舉'],['選理事一定要集會嗎','通訊選舉'],
 ['理事會選理事長要幾票','無記名單記法'],['理事長怎麼當選要多少票','無記名單記法'],
 ['監事要不要另外選','各有各的名額'],['理事和監事要分開選嗎','各有各的名額'],
 ['補選的人任期到什麼時候','沒有明文'],['候補遞補上來的任期怎麼算','沒有明文'],
 ['選舉是不是要通知縣府派人','派員列席'],['改選大會縣府會來人嗎','派員列席'],
 ['新舊任理事長要辦交接嗎','15日'],['理事長交接要交什麼','立案證書'],['誰來監交','監交人'],
];
const no=['合作社理事當選後不想當怎麼辦','公會改選一定要開大會嗎','理事長任期幾年','理事會多久開一次','會員大會要幾天前通知','前任理事長不交接怎麼辦','印章遺失怎麼補發','理事長辭職了要補選嗎','理事長票數一樣怎麼辦','國際性社團任期從哪天算','合作社改選要報縣府嗎','成立大會縣府會派人嗎','協會要不要請會計師'];
let bad=0;
yes.forEach(([q,e])=>{const a=A(q);const txt=a?(a.title+a.summary):'';if(!txt.includes(e)||!a.direct){bad++;console.log('✗',q,a&&a.title)}});
const mine=/(第一次理事會的那一天起算|候選人不一定要先登記|當選了不想當|覺得選舉過程不公平|改選完要報縣府|改選由理事會負責|改選原則上要集會|理事長由理事就常務|監事和理事一樣要由|補選或遞補的人|會員大會（包含改選）|新舊任理事長要辦交接)/;
no.forEach(q=>{const a=A(q);if(a&&mine.test(a.title)){bad++;console.log('✗誤觸',q,a.title)}});
console.log(bad?'失敗 '+bad:'全部通過');process.exit(bad?1:0);
